#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/valkey-valkey-9.1.3-alpine-arm64-oci ] || "$F" docker.io/valkey/valkey sha256:8ad17cd9f6481c2f453ed9c3c133978c960025ee6cd0db13a90712cb69b5b2a7 valkey/valkey:9.1.3-alpine images/valkey-valkey-9.1.3-alpine-arm64-oci
[ "$A" = arm64 ] || [ -f images/valkey-valkey-9.1.3-alpine-amd64.docker.tar ] || "$F" docker.io/valkey/valkey sha256:de6fbe9626fea9f6f297b6867d2c8cf8f0394ee5ed171613166fc093cb49d0a6 valkey/valkey:9.1.3-alpine images/valkey-valkey-9.1.3-alpine-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/valkey-valkey-9.1.3-alpine-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/valkey-valkey-9.1.3-alpine-arm64-oci
